//! The colors and icons that `branding:` accepts in action metadata.
//!
//! Ported from rhysd/actionlint at commit `011a6d1`: `BrandingColors` and `BrandingIcons` in
//! `rule_action.go`, lines 16-288. The icons are the Feather icon set. Until M7 replaces them
//! with a generated file (ADR 0011), keep them equal to those tables. The tests
//! `branding_colors_match_the_reference_table` and `branding_icons_match_the_reference_table`
//! compare them.
//!
//! <https://docs.github.com/en/actions/creating-actions/metadata-syntax-for-github-actions#branding>

use crate::go_case::eq_go_lower;

