/// Returns whether `color` is a branding color, comparing as the reference does after Go's
/// `strings.ToLower`.
#[must_use]
pub fn is_branding_color(color: &str) -> bool {
    BRANDING_COLORS
        .iter()
        .any(|known| eq_go_lower(color, known))
}

/// Returns whether `icon` is a branding icon, comparing as the reference does after Go's
/// `strings.ToLower`.
#[must_use]
pub fn is_branding_icon(icon: &str) -> bool {
    BRANDING_ICONS.iter().any(|known| eq_go_lower(icon, known))
}
